package lk.repairdesk.api.service; import lk.repairdesk.api.domain.User; import lk.repairdesk.api.exception.ResourceNotFoundException; import lk.repairdesk.api.repository.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; @Service public class CurrentUserService {private final UserRepository users; public CurrentUserService(UserRepository u){users=u;} public User get(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("Authenticated user not found"));}}